package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import java.io.*;
import java.nio.channels.*;
import java.nio.file.*;
import java.util.*;

/** One forced global vector before any HOME capture report; unknown force fences this live owner. */
public final class RatisDatabaseBackupJournal implements AutoCloseable {
    public static final int MAX_BYTES=DatabaseBackupDefinition.MAX_BYTES+32;
    public enum Phase { GATES, REQUESTS, CAPTURED, REPORTED, RELEASED, MATERIALIZING, COMPLETE, LOST, CANCELLED }
    public record Member(UUID fenceId,UUID groupId,UUID snapshotId,UUID owner,UUID replica,long ttlMillis,byte[] preparedDigest) {
        public Member { Objects.requireNonNull(fenceId);Objects.requireNonNull(groupId);Objects.requireNonNull(snapshotId);Objects.requireNonNull(owner);Objects.requireNonNull(replica);if(ttlMillis<1 || ttlMillis>RatisSnapshotCaptureRequest.maximumTtl(RatisSnapshotCaptureRequest.Mode.READ_ONLY).toMillis() || preparedDigest.length!=32)throw new IllegalArgumentException("Invalid frozen capture member");preparedDigest=preparedDigest.clone(); }
        @Override public byte[] preparedDigest(){return preparedDigest.clone();}
    }
    public record CohortRequest(UUID cohortId,UUID nodeIncarnation,UUID processIncarnation,UUID poolId,List<Member> members) {
        public CohortRequest { Objects.requireNonNull(cohortId);Objects.requireNonNull(nodeIncarnation);Objects.requireNonNull(processIncarnation);Objects.requireNonNull(poolId);if(members.isEmpty() || members.size()>1024)throw new IllegalArgumentException("Invalid cohort membership");members=members.stream().sorted(Comparator.comparing(Member::groupId,RangeDirectoryCodec.UUID_ORDER)).toList();var groups=new HashSet<UUID>();for(var m:members)if(!groups.add(m.groupId()))throw new IllegalArgumentException("Cohort owner/group changed"); }
    }
    public record Snapshot(Phase phase,List<CohortRequest> requests,List<SnapshotFenceStatus> captured,
                           List<DatabaseBackupManifest.Chunk> chunks,List<DatabaseBackupManifest.OperatorAsset> operators,long dispatchStartedMillis) {
        public Snapshot {requests=List.copyOf(requests);captured=List.copyOf(captured);chunks=List.copyOf(chunks);operators=List.copyOf(operators);}
    }
    @FunctionalInterface interface Force {
        void write(Path path,byte[] bytes)throws IOException;
        default void reforce(Path path)throws IOException {
            if(!Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS) || Files.exists(path.resolveSibling(path.getFileName()+".pending"),LinkOption.NOFOLLOW_LINKS))throw new IOException("Uncertain or foreign backup journal");
            try(var file=FileChannel.open(path,StandardOpenOption.READ,LinkOption.NOFOLLOW_LINKS)){file.force(true);}
            SessionJournalFiles.force(path.getParent());
        }
    }
    private final Path path;private final DatabaseBackupDefinition definition;private final DatabaseBackupManifest.Destination destination;
    private final RatisDatabaseBackupDriver.Policy policy;private final FileChannel ownership;private final FileLock lock;private final Force force;
    private Snapshot saved;private boolean closed,fenced;
    public static RatisDatabaseBackupJournal create(Path path,DatabaseBackupDefinition definition,DatabaseBackupManifest.Destination destination,RatisDatabaseBackupDriver.Policy policy)throws IOException{return new RatisDatabaseBackupJournal(path,definition,destination,policy,false,(p,b)->SessionJournalFiles.write(p,b,MAX_BYTES));}
    public static RatisDatabaseBackupJournal reopen(Path path,DatabaseBackupDefinition definition,DatabaseBackupManifest.Destination destination,RatisDatabaseBackupDriver.Policy policy)throws IOException{return new RatisDatabaseBackupJournal(path,definition,destination,policy,true,(p,b)->SessionJournalFiles.write(p,b,MAX_BYTES));}
    RatisDatabaseBackupJournal(Path path,DatabaseBackupDefinition definition,DatabaseBackupManifest.Destination destination,RatisDatabaseBackupDriver.Policy policy,boolean reopen,Force force)throws IOException{
        this.path=path.toAbsolutePath().normalize();this.definition=Objects.requireNonNull(definition);this.destination=Objects.requireNonNull(destination);this.policy=Objects.requireNonNull(policy);this.force=force;
        if(!Files.isDirectory(this.path.getParent(),LinkOption.NOFOLLOW_LINKS) || Files.isSymbolicLink(this.path))throw new IOException("Backup journal root absent or foreign");
        ownership=FileChannel.open(this.path.resolveSibling(this.path.getFileName()+".lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS);FileLock acquired=null;
        try{acquired=ownership.tryLock();if(acquired==null)throw new IOException("Backup journal already owned");lock=acquired;
            if(reopen){saved=decode(SessionJournalFiles.read(this.path,MAX_BYTES));if(!Arrays.equals(encode(saved),SessionJournalFiles.read(this.path,MAX_BYTES)))throw new IOException("Noncanonical backup journal");force.reforce(this.path);}
            else{if(Files.exists(this.path,LinkOption.NOFOLLOW_LINKS) || Files.exists(this.path.resolveSibling(this.path.getFileName()+".pending"),LinkOption.NOFOLLOW_LINKS))throw new IOException("Backup attempt already exists");saved=new Snapshot(Phase.GATES,List.of(),List.of(),List.of(),List.of(),0);persist(saved);}
        }catch(Throwable failure){if(acquired!=null)acquired.close();ownership.close();throw failure;}
    }
    public DatabaseBackupDefinition definition(){return definition;}public DatabaseBackupManifest.Destination destination(){return destination;}public RatisDatabaseBackupDriver.Policy policy(){return policy;}
    public synchronized Snapshot snapshot()throws IOException{open();return saved;}
    public synchronized void freezeRequests(List<CohortRequest> requests)throws IOException{
        open();if(requests.size()>policy.maximumCohorts())throw new IOException("Backup cohort quota exhausted");var next=new Snapshot(Phase.REQUESTS,requests.stream().sorted(Comparator.comparing(CohortRequest::cohortId,RangeDirectoryCodec.UUID_ORDER)).toList(),List.of(),List.of(),List.of(),saved.phase()==Phase.GATES?System.currentTimeMillis():saved.dispatchStartedMillis());validateRequests(next.requests());
        if(saved.phase()!=Phase.GATES){if(!Arrays.equals(encode(new Snapshot(Phase.REQUESTS,saved.requests(),List.of(),List.of(),List.of(),saved.dispatchStartedMillis())),encode(next)))throw new IOException("Frozen cohort request changed");return;}persist(next);
    }
    public synchronized void captured(List<SnapshotFenceStatus> statuses)throws IOException{
        open();if(saved.phase()!=Phase.REQUESTS && saved.phase()!=Phase.CAPTURED)throw new IOException("Global captures are not accepting results");
        var ordered=statuses.stream().sorted(Comparator.comparing(s->s.fence().fenceId(),RangeDirectoryCodec.UUID_ORDER)).toList();validateCaptured(saved.requests(),ordered);
        var next=new Snapshot(Phase.CAPTURED,saved.requests(),ordered,saved.chunks(),saved.operators(),saved.dispatchStartedMillis());if(saved.phase()==Phase.CAPTURED && !Arrays.equals(encode(saved),encode(next)))throw new IOException("Original global token vector changed");persist(next);
    }
    public synchronized void phase(Phase next)throws IOException{
        open();if(saved.phase()==next)return;
        if(saved.phase()==Phase.COMPLETE)throw new IOException("Published backup cannot change terminal phase");boolean forward=switch(saved.phase()){case CAPTURED->next==Phase.REPORTED;case REPORTED->next==Phase.RELEASED;case RELEASED->next==Phase.MATERIALIZING;case MATERIALIZING->next==Phase.COMPLETE;default->false;};
        if(!forward && next!=Phase.LOST && next!=Phase.CANCELLED)throw new IOException("Invalid backup phase transition");persist(new Snapshot(next,saved.requests(),saved.captured(),saved.chunks(),saved.operators(),saved.dispatchStartedMillis()));
    }
    public synchronized void copied(DatabaseBackupManifest.Chunk chunk)throws IOException{
        open();if(saved.phase()!=Phase.MATERIALIZING)throw new IOException("Backup is not materializing");var chunks=new ArrayList<>(saved.chunks());
        var old=chunks.stream().filter(c->c.groupId().equals(chunk.groupId()) && c.columnId().equals(chunk.columnId()) && c.ordinal()==chunk.ordinal()).findFirst();
        if(old.isPresent()){if(!Arrays.equals(chunkBytes(old.get()),chunkBytes(chunk)))throw new IOException("Copied chunk changed");return;}if(chunks.size()>=definition.limits().maximumChunks())throw new IOException("Backup chunks exhausted");chunks.add(chunk);persist(new Snapshot(saved.phase(),saved.requests(),saved.captured(),chunks,saved.operators(),saved.dispatchStartedMillis()));
    }
    public synchronized void operator(DatabaseBackupManifest.OperatorAsset asset)throws IOException{open();if(saved.phase()!=Phase.MATERIALIZING)throw new IOException("Backup is not materializing");var assets=new ArrayList<>(saved.operators());for(var old:assets)if(Arrays.equals(old.sha256(),asset.sha256())){if(!old.objectId().equals(asset.objectId()) || old.bytes()!=asset.bytes())throw new IOException("Operator asset changed");return;}assets.add(asset);persist(new Snapshot(saved.phase(),saved.requests(),saved.captured(),saved.chunks(),assets,saved.dispatchStartedMillis()));}
    public synchronized DatabaseBackupManifest manifest()throws IOException{open();return manifest(saved);}
    private DatabaseBackupManifest manifest(Snapshot state){var cohorts=state.requests().stream().map(c->new DatabaseBackupManifest.Cohort(c.nodeIncarnation(),c.poolId(),c.cohortId(),c.members().stream().map(Member::groupId).collect(java.util.stream.Collectors.toSet()))).toList();return new DatabaseBackupManifest(definition,destination,state.captured(),cohorts,state.chunks(),state.operators());}
    private void validateRequests(List<CohortRequest> requests)throws IOException{
        var groups=new HashSet<UUID>();var pools=new HashSet<String>();var ids=new HashSet<UUID>();var expected=new HashMap<UUID,SnapshotFence>();for(var d:definition.domains())for(var f:d.fences())for(var p:f.participants())expected.put(p.groupId(),f);
        for(var c:requests){if(!ids.add(c.cohortId()) || !pools.add(c.nodeIncarnation()+"/"+c.processIncarnation()+"/"+c.poolId()))throw new IOException("Cohort process/pool duplicated");for(var m:c.members()){var f=expected.get(m.groupId());if(f==null || !f.fenceId().equals(m.fenceId()) || !groups.add(m.groupId()) || m.ttlMillis()!=policy.retention().toMillis())throw new IOException("Cohort request coverage changed");var range=definition.domain(f.domainId()).directory().ranges().stream().filter(r->r.groupId().equals(m.groupId())).findFirst().orElseThrow();if(range.replicas().stream().noneMatch(r->r.replicaId().equals(m.replica()) && r.nodeIncarnation().equals(c.nodeIncarnation())))throw new IOException("Capture owner absent from frozen vector");}}
        if(!groups.equals(expected.keySet()))throw new IOException("Cohort request does not cover whole database");
    }
    private void validateCaptured(List<CohortRequest> requests,List<SnapshotFenceStatus> statuses)throws IOException{
        validateRequests(requests);var members=new HashMap<UUID,Member>();requests.forEach(c->c.members().forEach(m->members.put(m.groupId(),m)));var fences=new HashMap<UUID,SnapshotFence>();definition.domains().forEach(d->d.fences().forEach(f->fences.put(f.fenceId(),f)));
        for(var s:statuses){var f=fences.remove(s.fence().fenceId());if(f==null || !f.equals(s.fence()) || s.phase()!=SnapshotFenceStatus.Phase.INSTALLING || !s.allReady())throw new IOException("Captured vector lacks original held HOME");for(var p:s.progress()){var m=members.remove(p.groupId());var t=p.capture();if(m==null || t==null || !t.ownerIncarnation().equals(m.owner()) || !t.snapshotId().equals(m.snapshotId()))throw new IOException("Captured token changed original request");}}
        if(!fences.isEmpty() || !members.isEmpty())throw new IOException("Global capture vector incomplete");
    }
    private void persist(Snapshot next)throws IOException{byte[] bytes=encode(next);try{force.write(path,bytes);}catch(IOException failure){fenced=true;throw failure;}saved=next;}
    private byte[] encode(Snapshot state)throws IOException{return bytes(out->{out.writeInt(0x44424a4c);blob(out,definition.encode());uuid(out,destination.archiveId());uuid(out,destination.failureDomainId());out.writeLong(policy.retention().toMillis());out.writeLong(policy.maximumMaterialization().toMillis());out.writeInt(policy.maximumCohorts());out.writeLong(state.dispatchStartedMillis());out.writeInt(state.phase().ordinal());out.writeInt(state.requests().size());for(var c:state.requests()){uuid(out,c.cohortId());uuid(out,c.nodeIncarnation());uuid(out,c.processIncarnation());uuid(out,c.poolId());out.writeInt(c.members().size());for(var m:c.members()){uuid(out,m.fenceId());uuid(out,m.groupId());uuid(out,m.snapshotId());uuid(out,m.owner());uuid(out,m.replica());out.writeLong(m.ttlMillis());out.write(m.preparedDigest());}}out.writeInt(state.captured().size());for(var s:state.captured())blob(out,s.encode());out.writeInt(state.chunks().size());for(var c:state.chunks())blob(out,chunkBytes(c));out.writeInt(state.operators().size());for(var a:state.operators()){uuid(out,a.objectId());out.writeLong(a.bytes());out.write(a.sha256());}},definition.limits().maximumMetadataBytes());}
    private Snapshot decode(byte[] bytes)throws IOException{
        var in=new DataInputStream(new ByteArrayInputStream(bytes));if(in.readInt()!=0x44424a4c || !Arrays.equals(blob(in,DatabaseBackupDefinition.MAX_BYTES),definition.encode()) || !uuid(in).equals(destination.archiveId()) || !uuid(in).equals(destination.failureDomainId()) || in.readLong()!=policy.retention().toMillis() || in.readLong()!=policy.maximumMaterialization().toMillis() || in.readInt()!=policy.maximumCohorts())throw new IOException("Backup journal identity/policy changed");
        long started=in.readLong();int phase=in.readInt();if(phase<0 || phase>=Phase.values().length)throw new IOException("Invalid backup phase");int n=count(in,policy.maximumCohorts(),68);var requests=new ArrayList<CohortRequest>();for(int i=0;i<n;i++){UUID id=uuid(in),node=uuid(in),process=uuid(in),pool=uuid(in);int size=count(in,1024,120);var members=new ArrayList<Member>();for(int j=0;j<size;j++)members.add(new Member(uuid(in),uuid(in),uuid(in),uuid(in),uuid(in),in.readLong(),in.readNBytes(32)));requests.add(new CohortRequest(id,node,process,pool,members));}
        n=count(in,DatabaseBackupDefinition.MAX_RANGES,4);var captured=new ArrayList<SnapshotFenceStatus>();for(int i=0;i<n;i++)captured.add(SnapshotFenceStatus.decode(blob(in,SnapshotFenceStatus.MAX_BYTES)));n=count(in,definition.limits().maximumChunks(),4);var chunks=new ArrayList<DatabaseBackupManifest.Chunk>();for(int i=0;i<n;i++)chunks.add(readChunk(blob(in,4*NativeSstImportManifest.MAX_KEY_BYTES+160)));n=count(in,definition.limits().maximumColumnPairs(),56);var assets=new ArrayList<DatabaseBackupManifest.OperatorAsset>();for(int i=0;i<n;i++){UUID id=uuid(in);long size=in.readLong();assets.add(new DatabaseBackupManifest.OperatorAsset(id,in.readNBytes(32),size));}
        if(in.available()!=0)throw new IOException("Trailing backup journal");var state=new Snapshot(Phase.values()[phase],requests,captured,chunks,assets,started);if(started<0 || !requests.isEmpty() && started==0)throw new IOException("Invalid original dispatch deadline");if(!requests.isEmpty()){validateRequests(requests);if(!captured.isEmpty() || state.phase()==Phase.CAPTURED || state.phase()==Phase.REPORTED || state.phase()==Phase.RELEASED || state.phase()==Phase.MATERIALIZING || state.phase()==Phase.COMPLETE)validateCaptured(requests,captured);}else if(state.phase()!=Phase.GATES && state.phase()!=Phase.LOST && state.phase()!=Phase.CANCELLED)throw new IOException("Backup phase lacks requests");if(state.phase()==Phase.COMPLETE){try{manifest(state);}catch(IllegalArgumentException malformed){throw new IOException("COMPLETE lacks full archive graph",malformed);}}return state;
    }
    private static byte[] chunkBytes(DatabaseBackupManifest.Chunk c)throws IOException{return bytes(out->{uuid(out,c.domainId());uuid(out,c.groupId());uuid(out,c.columnId());out.writeLong(c.ordinal());out.writeLong(c.cut().term());out.writeLong(c.cut().index());bound(out,c.lowerInclusive());bound(out,c.upperExclusive());out.writeBoolean(c.objectId()!=null);if(c.objectId()!=null)uuid(out,c.objectId());out.writeLong(c.bytes());blob(out,c.sha256());out.writeLong(c.entries());bound(out,c.firstKey());bound(out,c.lastKey());},4*NativeSstImportManifest.MAX_KEY_BYTES+160);}
    private static DatabaseBackupManifest.Chunk readChunk(byte[] bytes)throws IOException{var in=new DataInputStream(new ByteArrayInputStream(bytes));UUID domain=uuid(in),group=uuid(in),column=uuid(in);long ordinal=in.readLong();var cut=new ApplyPosition(in.readLong(),in.readLong());byte[] lo=bound(in),hi=bound(in);UUID object=in.readBoolean()?uuid(in):null;long size=in.readLong();byte[] hash=blob(in,32);long rows=in.readLong();var chunk=new DatabaseBackupManifest.Chunk(domain,group,column,ordinal,cut,lo,hi,object,size,hash,rows,bound(in),bound(in));if(in.available()!=0)throw new IOException("Trailing chunk");return chunk;}
    @FunctionalInterface private interface Writer{void write(DataOutputStream out)throws IOException;}
    private static byte[] bytes(Writer write,int maximum)throws IOException{var buffer=new ByteArrayOutputStream();var out=new DataOutputStream(new OutputStream(){int used;void charge(int n)throws IOException{if(n>maximum-used)throw new IOException("Backup metadata exceeds bound before growth");used+=n;}public void write(int b)throws IOException{charge(1);buffer.write(b);}public void write(byte[] b,int offset,int n)throws IOException{charge(n);buffer.write(b,offset,n);}});write.write(out);return buffer.toByteArray();}
    private static void uuid(DataOutputStream out,UUID id)throws IOException{out.writeLong(id.getMostSignificantBits());out.writeLong(id.getLeastSignificantBits());}private static UUID uuid(DataInputStream in)throws IOException{return new UUID(in.readLong(),in.readLong());}
    private static void blob(DataOutputStream out,byte[] bytes)throws IOException{out.writeInt(bytes.length);out.write(bytes);}private static byte[] blob(DataInputStream in,int max)throws IOException{int n=in.readInt();if(n<0 || n>max || n>in.available())throw new IOException("Backup field exceeds bound");return in.readNBytes(n);}private static int count(DataInputStream in,int max,int minimum)throws IOException{int n=in.readInt();if(n<0 || n>max || (long)n*minimum>in.available())throw new IOException("Backup count exceeds remaining bytes");return n;}
    private static void bound(DataOutputStream out,byte[] value)throws IOException{if(value==null)out.writeInt(-1);else blob(out,value);}private static byte[] bound(DataInputStream in)throws IOException{int n=in.readInt();if(n==-1)return null;if(n<0 || n>NativeSstImportManifest.MAX_KEY_BYTES || n>in.available())throw new IOException("Invalid backup bound");return in.readNBytes(n);}
    private void open()throws IOException{if(closed || fenced || !lock.isValid())throw new IOException("Backup journal closed/fenced; exact reopen required");}
    @Override public synchronized void close()throws IOException{if(!closed){closed=true;try{lock.close();}finally{ownership.close();}}}
}
